(function () {
'use strict';
var Utils = window.Utils;
var HttpApi = window.HttpApi;
var Merchant = window.Merchant;
var Upload = window.MerchantUpload;
if (!Merchant) return;
if (!Merchant.requireLogin()) return;
var EDIT_KEY = 'merchant_content_editing';
var TYPE_LABEL = { article: '文章', qa: '问答', video: '视频' };
var state = {
type: 'article',
contentId: '',
submitting: false,
uploadingCover: false,
uploadingVideo: false,
goodsSel: [],
storeSel: [],
goodsResults: [],
storeOptions: [],
goodsLoaded: false,
storesLoaded: false,
form: {
title: '', summary: '', content: '', cover: '', category: '', tags: '',
answer: '', name: '', url: '', describe: '', duration: 0
}
};
function $(id) { return document.getElementById(id); }
function esc(value) {
return String(value == null ? '' : value)
.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function typeLabel() { return TYPE_LABEL[state.type] || '内容'; }
function fillFromStorage() {
var row = null;
try {
row = JSON.parse(localStorage.getItem(EDIT_KEY) || 'null');
localStorage.removeItem(EDIT_KEY);
} catch (e) { row = null; }
if (!row || String(row._id || row.id) !== state.contentId) return;
var f = state.form;
f.title = row.title || '';
f.summary = row.summary || '';
f.content = row.content || '';
f.cover = Utils.firstImage(row.cover) || '';
f.category = row.category || '';
f.tags = Array.isArray(row.tags) ? row.tags.join(',') : (row.tags || '');
f.answer = row.answer || '';
f.name = row.name || '';
f.url = row.url || row.video_url || '';
f.describe = row.describe || row.video_desc || '';
f.duration = Number(row.duration) || 0;
var links = row.links || {};
state.goodsSel = (Array.isArray(links.goods) ? links.goods : []).map(function (id) {
return { id: String(id), name: '商品#' + String(id).slice(-6) };
});
state.storeSel = (Array.isArray(links.stores) ? links.stores : []).map(function (id) {
return { id: String(id), name: '店铺#' + String(id).slice(-6) };
});
}
function syncFormFields() {
var f = state.form;
$('ce-title-input').value = f.title;
$('ce-summary').value = f.summary;
$('ce-content').value = f.content;
$('ce-question').value = f.title;
$('ce-answer').value = f.answer;
$('ce-video-name').value = f.name;
$('ce-describe').value = f.describe;
$('ce-category').value = f.category;
$('ce-tags').value = f.tags;
syncCover();
syncVideo();
}
function syncCover() {
var cover = Utils.firstImage(state.form.cover) || '';
['ce-article', 'ce-video'].forEach(function (prefix) {
var img = $(prefix + '-cover-img');
var plus = $(prefix + '-cover-plus');
if (!img || !plus) return;
if (cover) {
img.src = cover;
img.hidden = false;
plus.hidden = true;
} else {
img.removeAttribute('src');
img.hidden = true;
plus.hidden = false;
}
});
}
function syncVideo() {
var url = String(state.form.url || '');
var video = $('ce-video-preview');
var plus = $('ce-video-plus');
if (url) {
if (video.getAttribute('src') !== url) video.src = url;
video.hidden = false;
plus.hidden = true;
} else {
video.removeAttribute('src');
video.hidden = true;
plus.hidden = false;
}
}
function syncType() {
var label = typeLabel();
$('ce-title').textContent = (state.contentId ? '编辑' : '创作') + label;
$('ce-article').hidden = state.type !== 'article';
$('ce-qa').hidden = state.type !== 'qa';
$('ce-video').hidden = state.type !== 'video';
$('ce-common').hidden = state.type === 'video';
$('ce-submit').textContent = state.submitting ? '提交中…' : (state.contentId ? '保存修改' : '发布' + label);
$('ce-submit').disabled = state.submitting;
}
function renderChips() {
var goods = state.goodsSel.map(function (g) {
return '<span class="merchant-chip"><span>' + esc(g.name) + '</span>' +
'<button type="button" data-kind="goods" data-id="' + esc(g.id) + '" aria-label="移除商品">×</button></span>';
}).join('');
$('ce-goods-chips').innerHTML = goods + '<button class="merchant-chip merchant-chip--add" type="button" id="ce-goods-add">＋ 选择商品</button>';
var stores = state.storeSel.map(function (s) {
return '<span class="merchant-chip"><span>' + esc(s.name) + '</span>' +
'<button type="button" data-kind="store" data-id="' + esc(s.id) + '" aria-label="移除店铺">×</button></span>';
}).join('');
$('ce-store-chips').innerHTML = stores + '<button class="merchant-chip merchant-chip--add" type="button" id="ce-store-add">＋ 选择店铺</button>';
}
function toggleGoods(item) {
var id = String(item._id || item.id);
var idx = -1;
state.goodsSel.forEach(function (g, i) { if (g.id === id) idx = i; });
if (idx > -1) state.goodsSel.splice(idx, 1);
else state.goodsSel.push({ id: id, name: item.name || '商品' });
renderChips();
renderGoodsList();
}
function toggleStore(item) {
var id = String(item.id);
var idx = -1;
state.storeSel.forEach(function (s, i) { if (s.id === id) idx = i; });
if (idx > -1) state.storeSel.splice(idx, 1);
else state.storeSel.push({ id: id, name: item.name });
renderChips();
renderStoreList();
}
function renderGoodsList() {
var box = $('ce-goods-list');
if (!state.goodsLoaded) {
box.innerHTML = '<div class="loading"><span class="spinner" aria-hidden="true"></span><span>加载商品…</span></div>';
return;
}
if (!state.goodsResults.length) {
box.innerHTML = '<div class="empty"><strong>没有找到商品</strong><span>换个关键词试试</span></div>';
return;
}
box.innerHTML = state.goodsResults.map(function (g) {
var id = String(g._id || g.id);
var selected = state.goodsSel.some(function (x) { return x.id === id; });
var thumb = Utils.firstImage(g.goods_thumb || g.thumb || g.cover || '');
var price = g.goods_price != null ? g.goods_price : g.price;
return '<button class="merchant-pick' + (selected ? ' is-on' : '') + '" type="button" data-id="' + esc(id) + '">' +
(thumb ? '<img src="' + esc(thumb) + '" alt="" loading="lazy">' : '<span class="merchant-pick-thumb" aria-hidden="true">🛒</span>') +
'<span class="merchant-pick-main">' +
'<span class="merchant-pick-name">' + esc(g.name || '商品') + '</span>' +
(price != null ? '<span class="merchant-pick-sub">¥' + esc(price) + '</span>' : '') +
'</span>' +
'<span class="merchant-pick-check">✓</span>' +
'</button>';
}).join('');
Array.prototype.forEach.call(box.querySelectorAll('.merchant-pick'), function (btn) {
btn.addEventListener('click', function () {
var id = btn.getAttribute('data-id');
var item = state.goodsResults.filter(function (g) { return String(g._id || g.id) === id; })[0];
if (item) toggleGoods(item);
});
});
}
function renderStoreList() {
var box = $('ce-store-list');
if (!state.storesLoaded) {
box.innerHTML = '<div class="loading"><span class="spinner" aria-hidden="true"></span><span>加载店铺…</span></div>';
return;
}
if (!state.storeOptions.length) {
box.innerHTML = '<div class="empty"><strong>你还没有店铺</strong><span>请先在「我的店铺」创建</span></div>';
return;
}
box.innerHTML = state.storeOptions.map(function (s) {
var id = String(s.id);
var selected = state.storeSel.some(function (x) { return x.id === id; });
return '<button class="merchant-pick' + (selected ? ' is-on' : '') + '" type="button" data-id="' + esc(id) + '">' +
'<span class="merchant-pick-main">' +
'<span class="merchant-pick-name">' + esc(s.name) + '</span>' +
'<span class="merchant-pick-sub">' + (s.isPublic ? '公域展示中' : '未上公域') + '</span>' +
'</span>' +
'<span class="merchant-pick-check">✓</span>' +
'</button>';
}).join('');
Array.prototype.forEach.call(box.querySelectorAll('.merchant-pick'), function (btn) {
btn.addEventListener('click', function () {
var id = btn.getAttribute('data-id');
var item = state.storeOptions.filter(function (s) { return String(s.id) === id; })[0];
if (item) toggleStore(item);
});
});
}
function openGoods() {
$('ce-goods-modal').classList.add('is-open');
if (!state.goodsLoaded) searchGoods();
else renderGoodsList();
}
function searchGoods() {
state.goodsLoaded = false;
renderGoodsList();
HttpApi.goods.list({
keyword: $('ce-goods-keyword').value.trim(),
pageIndex: 1,
pageSize: 20
}).then(function (res) {
state.goodsLoaded = true;
state.goodsResults = res && res.code === 0 && res.rows ? res.rows : [];
renderGoodsList();
}).catch(function () {
state.goodsLoaded = true;
state.goodsResults = [];
renderGoodsList();
Merchant.toast('加载商品失败，请稍后重试');
});
}
function openStores() {
$('ce-store-modal').classList.add('is-open');
if (state.storesLoaded) {
renderStoreList();
return;
}
renderStoreList();
HttpApi.merchant.storeList({ pageIndex: 1, pageSize: 50 }).then(function (res) {
if (Merchant.authExpired(res)) return;
state.storesLoaded = true;
state.storeOptions = res && res.code === 0 ? (res.rows || []).map(function (s) {
return { id: String(s._id || s.id), name: s.name || '未命名店铺', isPublic: !!s.isPublic };
}) : [];
renderStoreList();
}).catch(function () {
state.storesLoaded = true;
state.storeOptions = [];
renderStoreList();
});
}
function uploadCover() {
if (state.uploadingCover || !Upload) return;
state.uploadingCover = true;
$('ce-article-cover-busy').hidden = false;
$('ce-video-cover-busy').hidden = false;
Upload.uploadImage().then(function (url) {
state.uploadingCover = false;
$('ce-article-cover-busy').hidden = true;
$('ce-video-cover-busy').hidden = true;
state.form.cover = url;
syncCover();
Merchant.toast('封面已上传');
}).catch(function (err) {
state.uploadingCover = false;
$('ce-article-cover-busy').hidden = true;
$('ce-video-cover-busy').hidden = true;
var msg = (err && err.message) || '';
if (/cancel/i.test(msg)) return;
Merchant.toast(msg || '上传失败');
});
}
function uploadVideo() {
if (state.uploadingVideo || !Upload) return;
state.uploadingVideo = true;
$('ce-video-busy').hidden = false;
Upload.uploadVideo().then(function (out) {
state.uploadingVideo = false;
$('ce-video-busy').hidden = true;
state.form.url = out.url;
state.form.duration = out.duration || 0;
syncVideo();
Merchant.toast('视频已上传');
}).catch(function (err) {
state.uploadingVideo = false;
$('ce-video-busy').hidden = true;
var msg = (err && err.message) || '';
if (/cancel/i.test(msg)) return;
Merchant.toast(msg || '上传失败');
});
}
function collectForm() {
var f = state.form;
f.title = (state.type === 'qa' ? $('ce-question') : $('ce-title-input')).value.trim();
f.summary = $('ce-summary').value.trim();
f.content = $('ce-content').value.trim();
f.answer = $('ce-answer').value.trim();
f.name = $('ce-video-name').value.trim();
f.describe = $('ce-describe').value.trim();
f.category = $('ce-category').value.trim();
f.tags = $('ce-tags').value.trim();
}
function submit() {
if (state.submitting) return;
collectForm();
var f = state.form;
if (state.type === 'article' && (!f.title || !f.content)) {
Merchant.toast('请填写标题与正文');
return;
}
if (state.type === 'qa' && (!f.title || !f.answer)) {
Merchant.toast('请填写问题与答案');
return;
}
if (state.type === 'video' && (!f.name || !f.url)) {
Merchant.toast('请填写标题并上传视频');
return;
}
var payload = {
type: state.type,
links: {
goods: state.goodsSel.map(function (g) { return g.id; }),
stores: state.storeSel.map(function (s) { return s.id; })
}
};
if (state.type === 'article') {
payload.title = f.title;
payload.summary = f.summary;
payload.content = f.content;
payload.cover = f.cover;
payload.category = f.category;
payload.tags = f.tags;
} else if (state.type === 'qa') {
payload.title = f.title;
payload.answer = f.answer;
payload.category = f.category;
payload.tags = f.tags;
} else {
payload.name = f.name;
payload.url = f.url;
payload.cover = f.cover;
payload.describe = f.describe;
payload.duration = Number(f.duration) || 0;
}
if (state.contentId) payload.id = state.contentId;
state.submitting = true;
syncType();
HttpApi.merchant.contentSave(payload).then(function (res) {
state.submitting = false;
syncType();
if (Merchant.authExpired(res)) return;
if (res && res.code === 0) {
Merchant.toast(res.msg || '发布成功');
Utils.track('merchant_content_save', { type: state.type, id: state.contentId || 'new' });
setTimeout(function () {
window.location.href = '/merchant/content.html?type=' + state.type;
}, 600);
} else {
Merchant.toast((res && res.msg) || '保存失败，请稍后重试');
}
}).catch(function () {
state.submitting = false;
syncType();
Merchant.toast('网络异常，请稍后重试');
});
}
function bindEvents() {
['ce-article-cover-box', 'ce-video-cover-box'].forEach(function (id) {
$(id).addEventListener('click', uploadCover);
});
$('ce-video-box').addEventListener('click', uploadVideo);
$('ce-goods-chips').addEventListener('click', function (e) {
var add = e.target.closest('#ce-goods-add');
if (add) {
openGoods();
return;
}
var removeBtn = e.target.closest('[data-kind="goods"]');
if (!removeBtn) return;
var id = removeBtn.getAttribute('data-id');
state.goodsSel = state.goodsSel.filter(function (g) { return g.id !== String(id); });
renderChips();
if ($('ce-goods-modal').classList.contains('is-open')) renderGoodsList();
});
$('ce-store-chips').addEventListener('click', function (e) {
var add = e.target.closest('#ce-store-add');
if (add) {
openStores();
return;
}
var removeBtn = e.target.closest('[data-kind="store"]');
if (!removeBtn) return;
var id = removeBtn.getAttribute('data-id');
state.storeSel = state.storeSel.filter(function (s) { return s.id !== String(id); });
renderChips();
if ($('ce-store-modal').classList.contains('is-open')) renderStoreList();
});
$('ce-goods-search-form').addEventListener('submit', function (e) {
e.preventDefault();
searchGoods();
});
$('ce-goods-done').addEventListener('click', function () {
$('ce-goods-modal').classList.remove('is-open');
});
$('ce-store-done').addEventListener('click', function () {
$('ce-store-modal').classList.remove('is-open');
});
['ce-goods-modal', 'ce-store-modal'].forEach(function (id) {
$(id).addEventListener('click', function (e) {
if (e.target === this) this.classList.remove('is-open');
});
});
$('ce-submit').addEventListener('click', submit);
}
function init() {
if (!HttpApi) return;
var params = new URLSearchParams(window.location.search);
var type = params.get('type') || '';
if (TYPE_LABEL[type]) state.type = type;
var id = params.get('id') || '';
if (id) {
state.contentId = String(id);
fillFromStorage();
}
syncFormFields();
syncType();
renderChips();
bindEvents();
Utils.track('merchant_content_edit_visit', { type: state.type, id: state.contentId || 'new' });
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
